mapper.select:
SELECT ${resource.projection} FROM ${resource.table}
WHERE USE_YN = 'Y'
ORDER BY ${resource.orderBy} OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

mapper.update:
UPDATE ${resource.table} SET USE_YN = 'N', UPDATED_AT = SYSTIMESTAMP,
  UPDATED_BY = #{actor}, VERSION_NO = VERSION_NO + 1
WHERE  AND VERSION_NO = #{version}

mapper.select:
SELECT COUNT(*) FROM ${resource.table} WHERE USE_YN = 'Y'
AND ${column} = #{value}
AND ${resource.identity} != #{identity}
AND VALID_FROM <= #{to}
AND (VALID_TO IS NULL OR VALID_TO >= #{from})
